SELECT p.name, MIN(s.name), SUM(oi.line_total_bdt) FROM order_items oi JOIN orders o ON o.order_id = oi.order_id JOIN product_variants v ON v.variant_id = oi.variant_id JOIN products p ON p.product_id = v.product_id JOIN sellers s ON s.seller_id = p.seller_id WHERE p.name = 'Classic Panjabi' AND NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2025-07-01' AND DATE '2026-06-30' GROUP BY p.name
